package model

type Colonizable interface {
	GetID() uint
	GetName() string
	GetOwner() uint
	Colonize(ownerID uint)
}

type PopulationCenter interface {
	CurrentPop() int64
	CurrentPopMillis() int64
	PopGrowth() int64
	MaxPop() int64
	Morale() int64
	UpdatePopulation()
}

type AgriculturalCenter interface {
	NumFarmers() int64
	Food() int64
}

type IndustrialCenter interface {
	NumWorkers() int64
	Industry() int64
	// Income returns the amount of money generated by
	// the industrial center.
	Income() int64

	Build(Project)
	AddBuilding(Project)
	GetCurrentProject() Project
	GetBuildQueue() []Project
	GetBuildings() []Project
	UpdateProduction()
}

type ResearchCenter interface {
	NumScientists() int64
	Research() int64
}

type MilitaryCenter interface {
	NumMarines() int64
	NumArmored() int64
}
